
/* ================= v7: final refinements ================= */
/* Drive: a category is its own page, not Home with a filter */
const _ovDrive6=VIEWS.drive;
VIEWS.drive=p=>{const pg=p[0]||'home';if(pg==='edit'||DTYPE.v==='all')return _ovDrive6(p);
const T={doc:['Docs','doc','doc','Document'],sheet:['Sheets','sheet','sheetI','Spreadsheet'],slides:['Slides','slides','slideI','Presentation'],pdf:['PDFs','pdf','pdfI','PDF'],image:['Images','image','imgI','Image'],form:['Forms','forms','forms','Form']}[DTYPE.v];
const L=DF.filter(f=>f.t===DTYPE.v);
const tpls=DTYPE.v==='doc'?['Blank','Meeting notes','Proposal','SOP','Weekly report']:DTYPE.v==='sheet'?['Blank','Budget','Content calendar','Tracker']:DTYPE.v==='slides'?['Blank','Pitch','Kick-off','Report']:[];
return dShell('drive/home',`${typeChips()}<div class="cathead"><span class="ft ${T[1]} big">${ic(T[2],22)}</span><div><h1 class="t1">${T[0]}</h1><p class="hint">${L.length} ${T[0].toLowerCase()} you can open in ${DRV.sp==='personal'?'Personal':'Library'} and shared with you</p></div><span class="grow"></span>${DTYPE.v==='form'?`<a class="btn primary sm" href="#/forms/list">${plate(app('forms'),18)}Open Forms</a>`:['pdf','image'].includes(DTYPE.v)?`<button class="btn primary sm" data-act="toast:Upload ${T[0]}.">${ic('upload',15)}Upload</button>`:`<a class="btn primary sm" href="#/drive/edit/${DTYPE.v}/new">${ic('plus',15,'',2.2)}New ${T[3].toLowerCase()}</a>`}</div>
${tpls.length?`<p class="over" style="margin:4px 0 8px">Start a new ${T[3].toLowerCase()}</p><div class="tpl-row">${tpls.map((n,i)=>`<a class="tpl ${!i?'new':''}" href="#/drive/edit/${DTYPE.v}/new">${i?`<span class="thumb" data-t="${T[1]}"></span>`:ic('plus',26)}<b>${n}</b></a>`).join('')}</div>`:''}
<div class="tb6" style="margin-top:6px"><span class="over">All ${T[0].toLowerCase()}</span><span class="grow"></span><select class="sel sm"><option>Anywhere</option><option>Library</option><option>Personal</option><option>Shared with me</option></select><select class="sel sm"><option>Last modified</option><option>Name</option></select></div>
${DTYPE.v==='form'?`<div class="tbl6"><div class="thd"><span>Form</span><span>Status</span><span>Responses</span><span></span><span></span><span></span></div>${FORMS.map(f=>`<a class="tr" href="#/forms/b/${f[0]}"><span class="t1c"><span class="ft forms" style="width:26px;height:26px;border-radius:7px">${ic('forms',13)}</span><b>${f[1]}</b></span><span>${f[2]}</span><span>${f[3]}</span><span></span><span></span><span></span></a>`).join('')}</div>`:L.length?fRows(L):emptyS(stack('mini-stack'),`No ${T[0].toLowerCase()} yet`,'Start one above or upload.','')}`,[['Drive'],[T[0]]])};
/* Docs editor: Google Docs-style ruler */
const _ed6=editor6;editor6=function(t,id){let h=_ed6(t,id);if(t==='doc')h=h.replace('<div class="dcanvas">',`<div class="dcanvas"><div class="ruler" aria-label="Ruler: drag the triangles to set margins and indents"><div class="rl-in">${Array.from({length:33},(_,i)=>`<i class="${i%4===0?'maj':i%2===0?'mid':''}">${i%4===0&&i>0&&i<32?i/4:''}</i>`).join('')}<span class="rl-mg l" title="Left margin"></span><span class="rl-mg r" title="Right margin"></span><span class="rl-ind" title="First-line indent"></span><span class="rl-tab" style="left:62%" title="Tab stop"></span></div></div>`).replace('<article class="dpage"','<div class="vruler"></div><article class="dpage"');return h};
/* Planner: focused Strategy map page (builder only), plan → project */
const _sm6=strategyModel;strategyModel=function(tab){if(tab!=='map')return _sm6(tab);const P=PLN();
const S=[[P.n,1],[org()==='aurj'?'Aurj Academy':'Funnel Done Right Challenge',0],[org()==='aurj'?'3 pieces of content daily.':'Q1 Delivery',0]];const stats=`${P.fa.length} focus areas · ${pobjs().length} objectives · ${pobjs().reduce((s,o)=>s+o.kpi.length,0)} KPIs · ${pobjs().reduce((s,o)=>s+o.tasks.length,0)} tasks · used by 1 plan`;
return plShell('planner/model',`<div class="smtop"><h1 class="t1">Strategy model</h1><div class="tabs6 inline">${[['map','Strategy map'],['kinds','Objective kinds'],['kpi','KPI types'],['fa','Focus areas'],['horizons','Time horizons'],['tpl','Templates']].map(([k,l])=>`<a href="#/planner/model/${k}" aria-selected="${k==='map'}">${l}</a>`).join('')}</div></div>
<div class="smbar2"><div class="stratpick"><button class="plsel" data-act="stratmenu" aria-haspopup="true">${ic('map',16)}${S[PS.strat][0]}${ic('down',14)}</button><small>${stats}</small></div><span class="grow"></span><button class="btn ghost sm" data-act="plnewstrat">${ic('plus',15)}New strategy</button><button class="btn primary sm" data-act="toast:Plan created with these focus areas, objectives, KPIs and tasks.:ok">${ic('planner',15)}Create a plan from it</button><button class="btn ghost sm" data-act="strat2proj">${plate(app('projects'),18)}Create a project from it</button><button class="iconbtn sm" aria-label="More" data-act="toast:Rename · Duplicate · Delete strategy">${ic('more',16)}</button></div>${builder(P)}`,[['Planner'],['Strategy model']],{wide:true})};
const _pp6=planPage;planPage=function(tab){return _pp6(tab).replace('<a class="btn quiet sm hide-m" href="#/planner/plan/slow/builder">See loading state</a>','').replace('<div class="tabs6 big">',`<div class="planacts"><button class="btn ghost sm" data-act="plan2proj">${plate(app('projects'),18)}Create a project from this plan</button><button class="iconbtn sm" aria-label="Plan actions" data-act="planmenu">${ic('more',16)}</button></div><div class="tabs6 big">`)};
const _vp6=VIEWS.planner;VIEWS.planner=p=>{if(p[0]==='alignment')return alignment6();return _vp6(p)};
const ALN={mode:'plans',open:new Set(['root','pl1','pl2'])};
function alignment6(){const P=PLN();const v=Math.round(pobjs().reduce((s,o)=>s+o.pr,0)/pobjs().length);
const box=(id,title,sub,pr,col,kids,lvl)=>`<div class="at-node" style="--c:${col}"><div class="at-box">${kids?`<button class="at-tg" data-act="altg:${id}" aria-label="${ALN.open.has(id)?'Collapse':'Expand'}">${ic(ALN.open.has(id)?'down':'right',13)}</button>`:''}<span class="ring xs" style="--v:${pr};--rc:${col}"></span><span><b>${title}</b><small>${sub}</small></span><span class="mono">${pr}%</span></div>${kids&&ALN.open.has(id)?`<div class="at-kids">${kids}</div>`:''}</div>`;
const objs=f=>f.obj.map((o,i)=>box(f.id+i,o.n,`${PEOPLE[o.ow][0]} · ${KST[o.st][0]}`,o.pr,f.c,'',3)).join('');
const tree=ALN.mode==='plans'?box('root',`${oname()} vision`,'2 plans',v,'#16171B',box('pl1',P.n,`${P.fa.length} focus areas · next review not set`,v,'#2B63F6',P.fa.map(f=>box(f.id,f.n,`${f.obj.length} objectives`,Math.round(f.obj.reduce((s,o)=>s+o.pr,0)/f.obj.length),f.c,objs(f),2)).join(''),1)+box('pl2','Q1 2027 Delivery','2 focus areas · child plan',0,'#7E5BF2','',1),0):box('root',P.n,'Objectives of this plan',v,'#2B63F6',P.fa.map(f=>box(f.id,f.n,`${f.obj.length} objectives`,0,f.c,objs(f),1)).join(''),0);
return plShell('planner/alignment',`${plTop('Alignment')}<div class="tb6">${vsw([['plans','Plans'],['objectives','Objectives of one plan']],ALN.mode,'almode')}<span class="grow"></span><button class="btn quiet sm" data-act="alall">Expand all</button><button class="iconbtn sm" aria-label="Zoom out" data-act="alz:-1">${ic('zout',16)}</button><button class="iconbtn sm" aria-label="Zoom in" data-act="alz:1">${ic('zin',16)}</button></div><div class="atree"><div class="at-world" style="transform:scale(${ALN.z||1})">${tree}</div></div><p class="hint" style="margin-top:8px">How plans roll up into each other, left to right. Click a box to open it; use the arrows to expand or collapse.</p>`,[['Planner'],['Alignment']])}
Object.assign(ACT,{almode:v=>{ALN.mode=v;draw()},altg:v=>{ALN.open.has(v)?ALN.open.delete(v):ALN.open.add(v);draw()},alall:()=>{['root','pl1','pl2',...PLN().fa.map(f=>f.id)].forEach(x=>ALN.open.add(x));draw()},alz:v=>{ALN.z=Math.min(1.4,Math.max(.6,(ALN.z||1)+(+v)*.1));draw()},
stratmenu:(v,t)=>{const r=t.getBoundingClientRect();const P=PLN();ctxMenu({preventDefault(){},clientX:r.left,clientY:r.bottom+4},[[ 'map',P.n,'plstrat:0'],['map',org()==='aurj'?'Aurj Academy':'Funnel Done Right Challenge','plstrat:1'],['map',org()==='aurj'?'3 pieces of content daily.':'Q1 Delivery','plstrat:2'],'-',['plus','New strategy','plnewstrat']])},
strat2proj:()=>dlg({icon:plate(app('projects'),52),title:'Create a project from this strategy',body:`<p>A new project starts with one section per focus area and one task per objective. KPIs stay in Planner.</p><div class="field" style="margin-top:12px"><label>Project name</label><input value="${PLN().n}"></div><div class="field"><label>Type</label><select><option>Internal</option><option>Client</option></select></div><p class="hint">Projects builds the project. Planner only sends the structure.</p>`,acts:[['Cancel','noop'],['Create project','toast:Project created in Projects.:ok','primary']]}),
plan2proj:()=>dlg({icon:plate(app('projects'),52),title:'Create a project from this plan',body:`<p>Turns “${PLN().n}” into a project: focus areas become sections and objectives become tasks with their owners and due dates. The plan keeps tracking progress and links to the project.</p><div class="field" style="margin-top:12px"><label>Project name</label><input value="${PLN().n}"></div><div class="row2"><div class="field"><label>Type</label><select><option>Internal</option><option>Client</option><option>Personal</option></select></div><div class="field"><label>Include</label><select><option>Objectives and tasks</option><option>Objectives only</option></select></div></div>`,acts:[['Cancel','noop'],['Create project','toast:Project created and linked to the plan.:ok','primary']]}),
planmenu:(v,t)=>{const r=t.getBoundingClientRect();ctxMenu({preventDefault(){},clientX:r.right-240,clientY:r.bottom+4},[['projects','Create a project from this plan','plan2proj'],['edit','Edit plan details','plnewplan'],['copy','Duplicate plan','toast:Duplicated.:ok'],['archive','Archive plan','toast:Archived.','danger']])}});
